-- Dental pack v1 and care-home pack v1 starter libraries (spec section 7, Phase 4).
-- SYNTHETIC DRAFT CONTENT. Same mechanism as the ambulance pack (0008): read-only library rows
-- (organisation_id NULL), inactive for every organisation until it adopts an item (copied as a DRAFT)
-- and a second person publishes it. Adopting from these two packs also requires the organisation to
-- have the pack enabled and a named specialist to have validated the content (adopt endpoint).
-- Intervals marked "proposed" are starting points only; they are NOT mandated frequencies.

ALTER TABLE requirement_template NO FORCE ROW LEVEL SECURITY;
ALTER TABLE requirement_template_version NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
  r record;
  t uuid;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('DEN-STF-01', 'GDC registration', 'STATUTORY', '[Draft pack - specialist validation required before use] Dentists Act 1984 (registration with the General Dental Council; renewal date taken from the GDC register)', 'https://www.gdc-uk.org/', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'EXPIRY', '{"roles":["DENTIST","DENTAL_NURSE","HYGIENIST"]}', 'WELL_LED'),
    ('DEN-STF-02', 'Professional indemnity', 'STATUTORY', '[Draft pack - specialist validation required before use] GDC requirement to hold appropriate indemnity (expiry from the policy schedule)', 'https://www.gdc-uk.org/', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'EXPIRY', '{}', 'WELL_LED'),
    ('DEN-STF-03', 'Radiation protection training (IR(ME)R)', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Ionising Radiation (Medical Exposure) Regulations 2017 (refresher interval proposed: 5 years; confirm with the radiation protection adviser)', 'https://www.legislation.gov.uk/uksi/2017/1322/contents', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":5}}', 'POLICY', 'DUE', '{"roles":["DENTIST"]}', 'SAFE'),
    ('DEN-STF-04', 'Medical emergencies and basic life support', 'GOOD_PRACTICE', '[Draft pack - specialist validation required before use] Resuscitation Council UK primary dental care guidance (refresher interval proposed: 1 year)', 'https://www.resus.org.uk/', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'DEPLOYMENT_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('DEN-STF-05', 'Decontamination and infection prevention training', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] HTM 01-05 and the Code of practice on infection prevention and control (interval proposed: 1 year)', 'https://www.gov.uk/government/publications/decontamination-in-primary-care-dental-practices', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'DUE', '{}', 'SAFE'),
    ('DEN-STF-06', 'Safeguarding training (adults and children)', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulated Activities Regulations 2014 reg 13; intercollegiate guidance (interval proposed: 3 years)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'DEPLOYMENT_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('DEN-STF-07', 'DBS suitability review', 'ORG_POLICY', '[Draft pack - specialist validation required before use] DBS checks have no expiry; review date set by local policy (proposed 3 years)', 'https://www.gov.uk/government/organisations/disclosure-and-barring-service', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'DEPLOYMENT_CRITICAL', 'REVIEW', '{}', 'SAFE'),
    ('DEN-STF-08', 'Immunisation status recorded (Hepatitis B)', 'GOOD_PRACTICE', '[Draft pack - specialist validation required before use] Green Book / occupational health advice for clinical staff (record only; clinical detail stays with occupational health)', 'https://www.gov.uk/government/collections/immunisation-against-infectious-disease-the-green-book', 'STAFF', '{"type":"EVENT_TRIGGERED"}', 'POLICY', 'DUE', '{}', 'SAFE'),
    ('DEN-EQ-01', 'Steriliser (autoclave) validation and periodic tests', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] HTM 01-05 and manufacturer instructions (validation yearly; daily/weekly tests per equipment schedule - proposed)', 'https://www.gov.uk/government/publications/decontamination-in-primary-care-dental-practices', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'SAFETY_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('DEN-EQ-02', 'Washer-disinfector validation', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] HTM 01-05 and manufacturer instructions (validation yearly - proposed)', 'https://www.gov.uk/government/publications/decontamination-in-primary-care-dental-practices', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'SAFETY_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('DEN-EQ-03', 'Compressor / pressure system examination', 'STATUTORY', '[Draft pack - specialist validation required before use] Pressure Systems Safety Regulations 2000 (interval from the written scheme of examination)', 'https://www.hse.gov.uk/pressure-systems/', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('DEN-EQ-04', 'X-ray equipment testing', 'STATUTORY', '[Draft pack - specialist validation required before use] Ionising Radiations Regulations 2017 (critical examination and routine tests; interval set by the radiation protection adviser - proposed 1 year)', 'https://www.hse.gov.uk/radiation/ionising/', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'SAFETY_CRITICAL', 'DUE', '{"requires":"radiography"}', 'SAFE'),
    ('DEN-EQ-05', 'Emergency equipment and medicines check', 'GOOD_PRACTICE', '[Draft pack - specialist validation required before use] Resuscitation Council UK (oxygen, AED, emergency drugs; check frequency proposed: weekly)', 'https://www.resus.org.uk/', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"DAYS","every":7}}', 'DEPLOYMENT_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('DEN-PRM-01', 'Radiation protection adviser appointed and local rules reviewed', 'STATUTORY', '[Draft pack - specialist validation required before use] Ionising Radiations Regulations 2017 (local rules review interval proposed: 3 years)', 'https://www.hse.gov.uk/radiation/ionising/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'POLICY', 'REVIEW', '{"requires":"radiography"}', 'WELL_LED'),
    ('DEN-PRM-02', 'Dental unit waterline controls', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] HTM 01-05 and HSE L8 (monitoring frequency from the water risk assessment; proposed: monthly)', 'https://www.hse.gov.uk/legionnaires/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":1}}', 'POLICY', 'DUE', '{}', 'SAFE'),
    ('DEN-PRM-03', 'Sharps safety review', 'STATUTORY', '[Draft pack - specialist validation required before use] Health and Safety (Sharp Instruments in Healthcare) Regulations 2013 (review interval proposed: 1 year)', 'https://www.hse.gov.uk/healthservices/needlesticks/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'REVIEW', '{}', 'SAFE'),
    ('DEN-PRM-04', 'Fire risk assessment', 'STATUTORY', '[Draft pack - specialist validation required before use] Regulatory Reform (Fire Safety) Order 2005 art 9 (review interval from competent person advice)', 'https://www.gov.uk/workplace-fire-safety-your-responsibilities', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('DEN-PRM-05', 'Electrical installation condition report', 'STATUTORY', '[Draft pack - specialist validation required before use] Electricity at Work Regulations 1989 (interval set by the inspecting electrician - proposed 5 years)', 'https://www.hse.gov.uk/electricity/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":5}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('DEN-ORG-01', 'Employers and public liability insurance', 'STATUTORY', '[Draft pack - specialist validation required before use] Employers Liability (Compulsory Insurance) Act 1969 (expiry from the certificate)', 'https://www.hse.gov.uk/simple-health-safety/insurance/', 'ORGANISATION', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'EXPIRY', '{}', 'WELL_LED'),
    ('DEN-ORG-02', 'Conscious sedation arrangements (only if offered)', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] CQC dental guidance and professional standards (apply only if sedation is offered; review interval proposed: 1 year)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'REVIEW', '{"onlyIfOffered":"sedation"}', 'SAFE')
  ) AS v(code, title, basis, ref, url, subject, recurrence, blocking, kind, rule, domain)
  LOOP
    IF EXISTS (SELECT 1 FROM requirement_template WHERE organisation_id IS NULL AND pack = 'DENTAL_V1' AND code = r.code) THEN
      CONTINUE;
    END IF;
    INSERT INTO requirement_template (organisation_id, pack, code, title) VALUES (NULL, 'DENTAL_V1', r.code, r.title) RETURNING id INTO t;
    INSERT INTO requirement_template_version
      (organisation_id, template_id, version, status, basis_type, regulation_ref, source_url, source_version_date,
       subject_type, applicability_rule, recurrence, blocking, deadline_kind, framework_mappings, approved_at)
    VALUES
      (NULL, t, 1, 'EFFECTIVE', r.basis::requirement_basis, r.ref, r.url, DATE '2026-10-01',
       r.subject::requirement_subject_type, r.rule::jsonb, r.recurrence::jsonb, r.blocking::requirement_blocking, r.kind,
       jsonb_build_array(jsonb_build_object('framework', 'CQC_SAF', 'domain', r.domain)), now());
  END LOOP;

  FOR r IN SELECT * FROM (VALUES
    ('CH-STF-01', 'NMC registration (registered nurses)', 'STATUTORY', '[Draft pack - specialist validation required before use] Nursing and Midwifery Order 2001 (annual retention; revalidation every 3 years tracked separately)', 'https://www.nmc.org.uk/', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'EXPIRY', '{"roles":["REGISTERED_NURSE"]}', 'WELL_LED'),
    ('CH-STF-02', 'DBS suitability review (including barred-list check where eligible)', 'ORG_POLICY', '[Draft pack - specialist validation required before use] DBS checks have no expiry; review date set by local policy (proposed 3 years)', 'https://www.gov.uk/government/organisations/disclosure-and-barring-service', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'DEPLOYMENT_CRITICAL', 'REVIEW', '{}', 'SAFE'),
    ('CH-STF-03', 'Identity and right to work', 'STATUTORY', '[Draft pack - specialist validation required before use] Immigration, Asylum and Nationality Act 2006 s15; follow-up for time-limited permission', 'https://www.gov.uk/check-job-applicant-right-to-work', 'STAFF', '{"type":"EVENT_TRIGGERED"}', 'STATUTORY', 'DUE', '{}', 'WELL_LED'),
    ('CH-STF-04', 'Medicines administration competence', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulated Activities Regulations 2014 reg 12; NICE managing medicines in care homes (reassessment interval proposed: 1 year)', 'https://www.nice.org.uk/guidance/sc1', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'DEPLOYMENT_CRITICAL', 'DUE', '{"roles":["CARE_ASSISTANT","SENIOR_CARER","REGISTERED_NURSE"]}', 'SAFE'),
    ('CH-STF-05', 'Safeguarding adults training', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulated Activities Regulations 2014 reg 13; intercollegiate guidance (interval proposed: 3 years)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'DEPLOYMENT_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('CH-STF-06', 'Moving and handling competence', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Manual Handling Operations Regulations 1992; LOLER for hoists (refresher interval proposed: 1 year)', 'https://www.hse.gov.uk/msd/manual-handling/', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'DEPLOYMENT_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('CH-STF-07', 'Fire safety and evacuation training', 'STATUTORY', '[Draft pack - specialist validation required before use] Regulatory Reform (Fire Safety) Order 2005 art 21 (interval proposed: 1 year)', 'https://www.gov.uk/workplace-fire-safety-your-responsibilities', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'DUE', '{}', 'SAFE'),
    ('CH-STF-08', 'Mental Capacity Act and DoLS awareness', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Mental Capacity Act 2005 (interval proposed: 3 years)', 'https://www.gov.uk/government/collections/mental-capacity-act-making-decisions', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'POLICY', 'DUE', '{}', 'EFFECTIVE'),
    ('CH-STF-09', 'Food hygiene training (catering staff)', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Food Hygiene (England) Regulations 2013 (refresher interval proposed: 3 years)', 'https://www.food.gov.uk/business-guidance/food-hygiene-training', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'POLICY', 'DUE', '{"roles":["CATERING"]}', 'SAFE'),
    ('CH-STF-10', 'Infection prevention and control training', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Code of practice on the prevention and control of infections (interval proposed: 1 year)', 'https://www.gov.uk/government/publications/the-health-and-social-care-act-2008-code-of-practice-on-the-prevention-and-control-of-infections-and-related-guidance', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'DUE', '{}', 'SAFE'),
    ('CH-STF-11', 'End-of-life care training', 'GOOD_PRACTICE', '[Draft pack - specialist validation required before use] NICE end of life care for adults quality standard (interval proposed: 3 years)', 'https://www.nice.org.uk/guidance/qs13', 'STAFF', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":3}}', 'NONE', 'DUE', '{}', 'CARING'),
    ('CH-SVC-01', 'Resident care-plan reviews up to date', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulated Activities Regulations 2014 reg 9 (the care record stays in the care-record system; this tracks review dates - proposed: monthly)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":1}}', 'POLICY', 'REVIEW', '{"externalSystem":"care-record"}', 'RESPONSIVE'),
    ('CH-SVC-02', 'DoLS / lawful authorisations in date', 'STATUTORY', '[Draft pack - specialist validation required before use] Mental Capacity Act 2005 Schedule A1 (authorisation expiry dates from the supervisory body)', 'https://www.gov.uk/government/collections/mental-capacity-act-making-decisions', 'SERVICE', '{"type":"EVENT_TRIGGERED"}', 'STATUTORY', 'EXPIRY', '{}', 'EFFECTIVE'),
    ('CH-SVC-03', 'Restrictive practice review', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulation 13 and Mental Capacity Act best-interests duties (review interval proposed: 3 months)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":3}}', 'POLICY', 'REVIEW', '{}', 'SAFE'),
    ('CH-SVC-04', 'Staffing dependency review', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulated Activities Regulations 2014 reg 18 (review interval proposed: monthly, and when residents change)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":1}}', 'POLICY', 'REVIEW', '{}', 'SAFE'),
    ('CH-SVC-05', 'Personal emergency evacuation plans reviewed', 'STATUTORY', '[Draft pack - specialist validation required before use] Regulatory Reform (Fire Safety) Order 2005 (review on admission, change of need and at least monthly - proposed)', 'https://www.gov.uk/workplace-fire-safety-your-responsibilities', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":1}}', 'POLICY', 'REVIEW', '{}', 'SAFE'),
    ('CH-SVC-06', 'Bed rails risk assessment and checks', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] MHRA/HSE guidance on bed rails (assessment on use and when needs change; equipment check interval proposed: monthly)', 'https://www.hse.gov.uk/healthservices/falls-from-bedrails.htm', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":1}}', 'SAFETY_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('CH-SVC-07', 'Laundry and infection control audit', 'GOOD_PRACTICE', '[Draft pack - specialist validation required before use] Code of practice on infection prevention and control (frequency proposed: monthly sample)', 'https://www.gov.uk/government/publications/the-health-and-social-care-act-2008-code-of-practice-on-the-prevention-and-control-of-infections-and-related-guidance', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":1}}', 'POLICY', 'DUE', '{}', 'SAFE'),
    ('CH-SVC-08', 'Visiting arrangements reviewed', 'REGULATORY_GUIDANCE', '[Draft pack - specialist validation required before use] Regulated Activities Regulations 2014 reg 9A (applies only in scope; review interval proposed: 6 months)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'SERVICE', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":6}}', 'NONE', 'REVIEW', '{"onlyIfInScope":"reg9A"}', 'CARING'),
    ('CH-EQ-01', 'Hoist and sling thorough examination (LOLER)', 'STATUTORY', '[Draft pack - specialist validation required before use] Lifting Operations and Lifting Equipment Regulations 1998 reg 9 (equipment lifting people: at least every 6 months, or per examination scheme)', 'https://www.hse.gov.uk/work-equipment-machinery/loler.htm', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":6}}', 'SAFETY_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('CH-EQ-02', 'Passenger lift thorough examination (LOLER)', 'STATUTORY', '[Draft pack - specialist validation required before use] Lifting Operations and Lifting Equipment Regulations 1998 reg 9 (every 6 months for lifts carrying people)', 'https://www.hse.gov.uk/work-equipment-machinery/loler.htm', 'EQUIPMENT', '{"type":"COMPLETION_BASED","interval":{"unit":"MONTHS","every":6}}', 'SAFETY_CRITICAL', 'DUE', '{}', 'SAFE'),
    ('CH-PRM-01', 'Fire risk assessment', 'STATUTORY', '[Draft pack - specialist validation required before use] Regulatory Reform (Fire Safety) Order 2005 art 9 (review interval from competent person advice)', 'https://www.gov.uk/workplace-fire-safety-your-responsibilities', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('CH-PRM-02', 'Legionella risk assessment and control scheme', 'STATUTORY', '[Draft pack - specialist validation required before use] HSE Approved Code of Practice L8 (review interval from competent person advice)', 'https://www.hse.gov.uk/legionnaires/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('CH-PRM-03', 'Gas safety check', 'STATUTORY', '[Draft pack - specialist validation required before use] Gas Safety (Installation and Use) Regulations 1998', 'https://www.hse.gov.uk/gas/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('CH-PRM-04', 'Electrical installation condition report', 'STATUTORY', '[Draft pack - specialist validation required before use] Electricity at Work Regulations 1989 (interval set by the inspecting electrician - proposed 5 years)', 'https://www.hse.gov.uk/electricity/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":5}}', 'STATUTORY', 'DUE', '{}', 'SAFE'),
    ('CH-PRM-05', 'Food hygiene rating and HACCP records', 'STATUTORY', '[Draft pack - specialist validation required before use] Food Hygiene (England) Regulations 2013 (review interval proposed: 1 year)', 'https://www.food.gov.uk/', 'PREMISES', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'REVIEW', '{}', 'SAFE'),
    ('CH-ORG-01', 'Statement of purpose and registration details reviewed', 'STATUTORY', '[Draft pack - specialist validation required before use] Care Quality Commission (Registration) Regulations 2009 (review interval proposed: 1 year, and on any change)', 'https://www.cqc.org.uk/guidance-regulation/regulations-service-providers-and-managers', 'ORGANISATION', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'POLICY', 'REVIEW', '{}', 'WELL_LED'),
    ('CH-ORG-02', 'Employers and public liability insurance', 'STATUTORY', '[Draft pack - specialist validation required before use] Employers Liability (Compulsory Insurance) Act 1969 (expiry from the certificate)', 'https://www.hse.gov.uk/simple-health-safety/insurance/', 'ORGANISATION', '{"type":"COMPLETION_BASED","interval":{"unit":"YEARS","every":1}}', 'STATUTORY', 'EXPIRY', '{}', 'WELL_LED')
  ) AS v(code, title, basis, ref, url, subject, recurrence, blocking, kind, rule, domain)
  LOOP
    IF EXISTS (SELECT 1 FROM requirement_template WHERE organisation_id IS NULL AND pack = 'CARE_HOME_V1' AND code = r.code) THEN
      CONTINUE;
    END IF;
    INSERT INTO requirement_template (organisation_id, pack, code, title) VALUES (NULL, 'CARE_HOME_V1', r.code, r.title) RETURNING id INTO t;
    INSERT INTO requirement_template_version
      (organisation_id, template_id, version, status, basis_type, regulation_ref, source_url, source_version_date,
       subject_type, applicability_rule, recurrence, blocking, deadline_kind, framework_mappings, approved_at)
    VALUES
      (NULL, t, 1, 'EFFECTIVE', r.basis::requirement_basis, r.ref, r.url, DATE '2026-10-01',
       r.subject::requirement_subject_type, r.rule::jsonb, r.recurrence::jsonb, r.blocking::requirement_blocking, r.kind,
       jsonb_build_array(jsonb_build_object('framework', 'CQC_SAF', 'domain', r.domain)), now());
  END LOOP;
END $$;

ALTER TABLE requirement_template FORCE ROW LEVEL SECURITY;
ALTER TABLE requirement_template_version FORCE ROW LEVEL SECURITY;
